<script setup lang="ts">
import{ref,computed}from'vue';const emit=defineEmits(['selected']);const filter=ref('');const icons=Object.entries(import.meta.glob('/src/assets/icons/svg/*.svg',{eager:true,query:'?url',import:'default'})).map(([path,url])=>({name:path.split('/').pop()!.replace('.svg',''),url:String(url)}));const filtered=computed(()=>icons.filter(i=>i.name.includes(filter.value)));defineExpose({reset:()=>filter.value=''})
</script><template><div><el-input v-model="filter" placeholder="请输入图标名称" clearable/><div class="icon-list"><button v-for="i in filtered" :key="i.name" type="button" @click="emit('selected',i.name)" :title="i.name"><img :src="i.url" width="24" height="24"/><span>{{i.name}}</span></button></div></div></template><style scoped>.icon-list{max-height:260px;overflow:auto;display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:8px}.icon-list button{border:0;background:#f4f6fa;display:flex;align-items:center;gap:6px;padding:8px;overflow:hidden;cursor:pointer}.icon-list span{overflow:hidden;text-overflow:ellipsis}</style>